declare class Image {
/**
 * Create a bmp image of the current screen image
 * @param filename Filename you want to write. The file will be overwritten if it already exists.
 * @param resolution The resolution to write the image at. Can be Image.SCREEN, Image.X2 or Image.X4. If omitted screen resolution will be used
 * @param write_8bit BMP images can be written using either 8 bit (256 colours) or 24 bit (16 million colours). If this is true then an 8 bit image will be written. If false (or omitted) a 24 bit image will be written.
 * @param options For 8 bit images (see 'write_8bit' argument) the palette can be optimised (Image.OPTIMISE) and/or dithered (Image.DITHER) and/or compressed (Image.COMPRESS) If 0 (or omitted) no palette optimising, dithering or compression will be done.
 */
    static WriteBMP(filename: string, resolution?: number, write_8bit?: boolean, options?: number): void;

/**
 * Create a gif image of the current screen image
 * @param filename Filename you want to write. The file will be overwritten if it already exists.
 * @param resolution The resolution to write the image at. Can be Image.SCREEN, Image.X2 or Image.X4. If omitted screen resolution will be used
 * @param palette The palette can be optimised (Image.OPTIMISE) and/or dithered (Image.DITHER). If 0 (or omitted) no palette optimising or dithering will be done.
 */
    static WriteGIF(filename: string, resolution?: number, palette?: number): void;

/**
 * Create a jpeg image of the current screen image
 * @param filename Filename you want to write. The file will be overwritten if it already exists.
 * @param resolution The resolution to write the image at. Can be Image.SCREEN, Image.X2 or Image.X4. If omitted screen resolution will be used
 * @param quality Quality of the image in percent. Can be in the range [10,100]. If omitted, the quality is 90.
 */
    static WriteJPEG(filename: string, resolution?: number, quality?: number): void;

/**
 * Create a png image of the current screen image
 * @param filename Filename you want to write. The file will be overwritten if it already exists.
 * @param resolution The resolution to write the image at. Can be Image.SCREEN, Image.X2 or Image.X4. If omitted screen resolution will be used
 * @param write_8bit PNG images can be written using either 8 bit (256 colours) or 24 bit (16 million colours). If this is true then an 8 bit image will be written. If false (or omitted) a 24 bit image will be written.
 * @param palette For 8 bit images (see 'write_8bit' argument) the palette can be optimised (Image.OPTIMISE) and/or dithered (Image.DITHER). If 0 (or omitted) no palette optimising or dithering will be done.
 */
    static WritePNG(filename: string, resolution?: number, write_8bit?: boolean, palette?: number): void;

/** If compression is done for 8 bit bmp images. */
    static COMPRESS: number;
/** If dithering is done for 8 bit images. */
    static DITHER: number;
/** If palette optimisation is done for 8 bit images. */
    static OPTIMISE: number;
/** Image will be created at screen resolution. */
    static SCREEN: number;
/** Image will be created at 2x screen resolution. */
    static X2: number;
/** Image will be created at 4x screen resolution. */
    static X4: number;
}


/** Object function argument in Error */
interface ErrorArgument_options {
    /** An optional function to call to apply a custom autofix. If omitted no autofix will be possible (default). The include object is accessible in the function using the 'this' keyword. As this function can do anything, please use with extreme care to ensure that the objects and data in PRIMER remain valid and do not get corrupted. For example, a custom autofix should not delete another object that has an autofix which still has to run, or delete the model that is being checked! Hoist with his own petard... */
    autofixFunction?: () => void;
    /** A message to describe the custom autofix. If omitted no autofix will be possible (default) */
    autofixMessage?: string;
    /** A detailed error message. If omitted no detailed message will be given (default) */
    details?: string;
}


/** Object function argument in Warning */
interface WarningArgument_options {
    /** An optional function to call to apply a custom autofix. If omitted no autofix will be possible (default). The include object is accessible in the function using the 'this' keyword. As this function can do anything, please use with extreme care to ensure that the objects and data in PRIMER remain valid and do not get corrupted. For example, a custom autofix should not delete another object that has an autofix which still has to run, or delete the model that is being checked! Hoist with his own petard... */
    autofixFunction?: () => void;
    /** A message to describe the custom autofix. If omitted no autofix will be possible (default) */
    autofixMessage?: string;
    /** A detailed warning message. If omitted no detailed message will be given (default) */
    details?: string;
}


/** Object function argument in Write */
interface WriteArgument_options {
    /** If true then the output file will be written out in binary. If false (default) then an ascii file will be written. */
    binary?: boolean;
    /** If true then the output file will be compressed. If false (default) then an uncompressed file will be written. */
    compress?: boolean;
    /** Compression level for .gz and .zip files. Must be in the range 1 to 9 with 1 being the least compression (fastest speed) to 9 being the greatest compression (slowest speed) */
    compressLevel?: number;
    /** This option can be used to specify the mode of compression. Can be Include.KEEP_ORIGINAL or Include.INDIVIDUAL_GZIP or Include.INDIVIDUAL_ZIP */
    compressMode?: number;
    /** If true then the begining of the file (*CONTROL etc) file is written out in ascii. If false (default) then the entire file is converted to binary.  */
    fileStartAscii?: boolean;
    /** If true then i10 format will be used to write the file. If false (default) then the normal Ansys LS-DYNA format will be used. */
    i10?: boolean;
    /** If true then large format will be used to write the file. If false (default) then the normal Ansys LS-DYNA format will be used. Note that large format is only available from version R7.1 and above. */
    large?: boolean;
    /** The method used to write include paths. Can be Include.ABSOLUTE (default) or Include.RELATIVE */
    path?: number;
    /** The directory separator used when writing include files. Can be Include.NATIVE (default), Include.UNIX or Include.WINDOWS */
    separator?: number;
    /** The Ansys LS-DYNA version used to write the file. Can be "971R5", "971R4", "971R3", "970v6763" etc (see the version popup in Model-&gt;Write '&gt;&gt;&gt; Ansys LS-DYNA output options' for a full list). See also Options.dyna_version */
    version?: string;
}

