    /** Z coordinate of centre of gravity */
    cofgz: number;
    /** XX inertia */
    inerxx: number;
    /** XY inertia */
    inerxy: number;
    /** XZ inertia */
    inerxz: number;
    /** YY inertia */
    ineryy: number;
    /** YZ inertia */
    ineryz: number;
    /** ZZ inertia */
    inerzz: number;
    /** Mass */
    mass: number;
