    tt2: number;
/** Section type. Can be Section.ALE1D, Section.ALE2D, Section.BEAM, Section.DISCRETE, Section.IGA_SHELL, Section.IGA_SOLID, Section.POINT_SOURCE, Section.SEATBELT, Section.SHELL, Section.SOLID, Section.SPH or Section.TSHELL */
    readonly type: number;
/** If _USER option is set. Can be true or false */
